#!/usr/bin/env python3
"""Validator recompute for research/jv_nagao_hilbert_20261112 (independent of the producer's
band.py / replay_compare.py / rho_compare.py and of the Rust negrho_rescore tool).
Reads raw JSON records only. Writes a JSON summary to argv[1]."""
import json, glob, math, os, sys, hashlib
import numpy as np

ROOT = '/home/user/crypto'
ST = ROOT + '/research/jv_nagao_hilbert_20261112'
VA = ST + '/validation'
RS = ROOT + '/research/jv_cover_negrho_rescore_20261101/results'
FB = ROOT + '/research/jv_cover_fbline_20261102/results'
PRIMES = [1301, 1451, 1601]
SEEDS = [1, 2, 3]
out = {}

def load(p):
    with open(p) as f:
        return json.load(f)

def flat(x, pre=''):
    r = {}
    if isinstance(x, dict):
        for k, v in x.items():
            r.update(flat(v, pre + '.' + k))
    elif isinstance(x, list):
        for i, v in enumerate(x):
            r.update(flat(v, pre + '[%d]' % i))
    else:
        r[pre] = x
    return r

def diff(a, b, ignore_ms=True):
    fa, fb = flat(a), flat(b)
    keys = set(fa) | set(fb)
    d = []
    for k in sorted(keys):
        if ignore_ms and k.endswith('_ms'):
            continue
        if fa.get(k, '<missing>') != fb.get(k, '<missing>') or (type(fa.get(k)) != type(fb.get(k))):
            d.append(k)
    return len([k for k in keys if not (ignore_ms and k.endswith('_ms'))]), d

# ---------- A. cover replay ----------
labels = ['aa_line_p1301_s1'] + ['hilbert_p%d_s%d' % (p, s) for p in PRIMES for s in SEEDS]
rep = {}
for L in labels:
    a = load(ST + '/results/%s.json' % L); b = load(VA + '/replay/%s.json' % L)
    n, d = diff(a, b)
    r0, r1 = a[0], b[0]
    rep[L] = dict(fields=n, differing=d, total_muls=r0['total_muls'], equal_total=r0['total_muls'] == r1['total_muls'],
                  correct=(r0['correct'], r1['correct']), solved=(r0['solved'], r1['solved']),
                  mismatches=(r0['mismatches'], r1['mismatches']), digest=r0['relation_digest'],
                  s_committed=r0['s'], s_recomputed=r0['total_muls'] / (r0['c_add_e'] * math.sqrt(r0['l'])),
                  hcheck=(r0.get('hilbert_check_muls'), r1.get('hilbert_check_muls')),
                  pts=(r0.get('f4_muls_per_test_sum'), r1.get('f4_muls_per_test_sum')), f4=r0['f4_muls'])
    # internal arithmetic: total_muls = sum of phase muls
    parts = ['setup_muls', 'base_muls', 'stream_muls', 'weil_muls', 'f4_muls', 'lin_muls', 'post_muls', 'verify_muls', 'la_muls']
    rep[L]['phase_sum_equals_total'] = sum(r0[k] for k in parts) == r0['total_muls']
out['cover_replay'] = rep
# single thread
a = load(ST + '/results/hilbert_p1301_s1.json'); b = load(VA + '/replay_1thread/hilbert_p1301_s1.json')
n, d = diff(a, b)
out['cover_replay_1thread'] = dict(fields=n, differing=d, f4=b[0]['f4_muls'], per_test_sum=b[0]['f4_muls_per_test_sum'],
    rel=(b[0]['f4_muls_per_test_sum'] - b[0]['f4_muls']) / b[0]['f4_muls'], hcheck_1t=b[0]['hilbert_check_muls'],
    hcheck_committed=a[0]['hilbert_check_muls'], hcheck_1t_over_f4=b[0]['hilbert_check_muls'] / b[0]['f4_muls'],
    hcheck_committed_over_f4=a[0]['hilbert_check_muls'] / a[0]['f4_muls'])

# ---------- B. stage 1 vs frozen line records ----------
st1 = {}
for p in PRIMES:
    for s in SEEDS:
        A = load(FB + '/line_p%d_s%d.json' % (p, s))[0]; Bv = load(ST + '/results/hilbert_p%d_s%d.json' % (p, s))[0]
        st1['p%d_s%d' % (p, s)] = dict(SB_SA=Bv['s'] / A['s'], f4_ratio=Bv['f4_muls'] / A['f4_muls'],
            native_ratio=Bv['f4_native_ops'] / A['f4_native_ops'],
            same_digest=A['relation_digest'] == Bv['relation_digest'], same_rel=A['relations'] == Bv['relations'],
            same_res=A['residuals'] == Bv['residuals'], same_dec=A['decompositions'] == Bv['decompositions'],
            same_l=A['l'] == Bv['l'], correct=(A['correct'], Bv['correct']), fallbacks=Bv['hilbert_fallbacks'],
            applied=Bv['hilbert_applied'], fallback_frac=Bv['hilbert_fallbacks'] / (Bv['hilbert_applied'] + Bv['hilbert_fallbacks']))
aa = load(ST + '/results/aa_line_p1301_s1.json'); fr = load(FB + '/line_p1301_s1.json')
n, d = diff(fr, aa)
st1['aa_vs_frozen'] = dict(fields=n, differing=d)
out['stage1'] = st1

# ---------- C. rho records ----------
NATK = ['canon_cmp', 'hash', 'dp_check', 'scalar_ops', 'table_ops', 'cycle_cmp']
cover = {(p, s): load(ST + '/results/hilbert_p%d_s%d.json' % (p, s))[0] for p in PRIMES for s in SEEDS}

def rho_rec(path):
    return load(path)[0]

def ref_old(p, s, r):
    if r <= 1:
        for x in load(RS + '/inputs/old_rhostrong/rhostrong_p%d_run%d.json' % (p, r)):
            if x['seed'] == s:
                return x
        raise KeyError
    return rho_rec(RS + '/new/rhostrong_p%d_s%d_run%d.json' % (p, s, r))

checks = dict(n=0, bad=[])
fresh = {}
for d_, rr in [('rho_fresh_run0-13', range(0, 14)), ('rho_fresh_run14-27', range(14, 28))]:
    for p in PRIMES:
        for s in SEEDS:
            for r in rr:
                x = rho_rec(VA + '/%s/rhostrong_p%d_s%d_run%d.json' % (d_, p, s, r))
                checks['n'] += 1
                ok = (x['correct'] is True and x['capped'] is False and x['negation'] is True and x['batch'] == 16 and x['r'] == 256
                      and x['dp_bits'] == 16 and x['p'] == p and x['seed'] == s and x['run'] == r and x['l'] == cover[(p, s)]['l']
                      and x['c_add_e'] == cover[(p, s)]['c_add_e'])
                # internal: muls_tuned / harness from ops, s from muls
                o = x['ops']
                mt = 24 * o['mul'] + 18 * o['sq'] + 62 * o['inv']; mh = 55 * o['mul'] + 55 * o['sq'] + 166 * o['inv']
                ok = ok and mt == x['muls_tuned'] and mh == x['muls_harness']
                ok = ok and abs(x['s_tuned'] - mt / (331.0 * math.sqrt(x['l']))) < 1e-12 and abs(x['s_harness'] - mh / (331.0 * math.sqrt(x['l']))) < 1e-12
                ok = ok and o['walk_adds'] == x['steps']
                if not ok:
                    checks['bad'].append((d_, p, s, r))
                fresh[(p, s, r)] = x
out['rho_record_checks'] = checks
# runs 0-13 vs reference of the 20261101 study
same, dif = 0, []
for p in PRIMES:
    for s in SEEDS:
        for r in range(14):
            n, d = diff(ref_old(p, s, r), fresh[(p, s, r)])
            d = [k for k in d if not k.endswith('wall_ms')]
            if d:
                dif.append(((p, s, r), d))
            else:
                same += 1
out['rho_0_13_vs_reference'] = dict(identical=same, differing=dif)

# ---------- D. ratios ----------
def nat(x):
    return sum(x['ops'][k] for k in NATK) / math.sqrt(x['l'])

def refset(rr):
    return [fresh[(p, s, r)] for p in PRIMES for s in SEEDS for r in rr]

cov_S = {p: np.array([cover[(p, s)]['s'] for s in SEEDS]) for p in PRIMES}
cov_N = {p: np.array([cover[(p, s)]['f4_native_ops'] / math.sqrt(cover[(p, s)]['l']) for s in SEEDS]) for p in PRIMES}
# recompute s from total_muls
for p in PRIMES:
    for s in SEEDS:
        c = cover[(p, s)]
        assert abs(c['s'] - c['total_muls'] / (c['c_add_e'] * math.sqrt(c['l']))) < 1e-14 * c['s'] + 1e-15

def gm(v):
    return float(np.exp(np.mean(np.log(v))))

def point(rs, unit, w, p):
    key = 's_harness' if unit == 'U1' else 's_tuned'
    ref = np.mean([x[key] + w * nat(x) for x in rs])
    ic = gm(cov_S[p] + w * cov_N[p])
    return ic / ref, ic, ref

sets = {'pooled_0-13': range(0, 14), 'fresh_14-27': range(14, 28), 'combined_0-27': range(0, 28)}
res = {}
for nm, rr in sets.items():
    rs = refset(rr)
    st = np.array([x['steps'] / math.sqrt(x['l']) for x in rs])
    theory = math.sqrt(math.pi / 4) / math.sqrt(1 - 1 / 256)
    se = st.std(ddof=1) / math.sqrt(len(st))
    cell = {'n': len(rs), 'mean_s_harness': float(np.mean([x['s_harness'] for x in rs])),
            'mean_s_tuned': float(np.mean([x['s_tuned'] for x in rs])),
            'mean_nat_rho': float(np.mean([nat(x) for x in rs])),
            'steps_over_sqrtl': float(st.mean()), 'se': float(se), 'z': float((st.mean() - theory) / se), 'theory': theory}
    for unit in ['U1', 'U2']:
        for w in [0, 0.1, 1]:
            for p in PRIMES:
                r_, ic, ref = point(rs, unit, w, p)
                cell['%s_w%s_p%d' % (unit, w, p)] = dict(ratio=r_, ic=ic, rho=ref)
    # crossover model p*
    for unit in ['U1', 'U2']:
        G = np.mean([math.log(cell['%s_w0_p%d' % (unit, p)]['ratio']) + 2.10 * math.log(p) for p in PRIMES])
        cell['pstar_' + unit] = math.exp(G / 2.10)
    res[nm] = cell
out['ratios'] = res

# ---------- E. bootstrap (own RNG, same frozen design) ----------
def boot(rr, B=20000, seed=20261112):
    rng = np.random.default_rng(seed)
    # per instance group arrays
    groups = {}
    for p in PRIMES:
        for s in SEEDS:
            xs = [fresh[(p, s, r)] for r in rr]
            groups[(p, s)] = dict(h=np.array([x['s_harness'] for x in xs]), t=np.array([x['s_tuned'] for x in xs]),
                                  n=np.array([nat(x) for x in xs]))
    keys = list(groups)
    res = {}
    acc = {(u, w, p): np.empty(B) for u in ['U1', 'U2'] for w in [0, 0.1, 1] for p in PRIMES}
    for b in range(B):
        H, T, N = [], [], []
        for k in keys:
            g = groups[k]; m = len(g['h'])
            idx = rng.integers(0, m, m)
            H.append(g['h'][idx]); T.append(g['t'][idx]); N.append(g['n'][idx])
        H = np.concatenate(H); T = np.concatenate(T); N = np.concatenate(N)
        for p in PRIMES:
            si = rng.integers(0, 3, 3)
            cs = cov_S[p][si]; cn = cov_N[p][si]
            for w in [0, 0.1, 1]:
                icw = math.exp(np.mean(np.log(cs + w * cn)))
                acc[('U1', w, p)][b] = icw / np.mean(H + w * N)
                acc[('U2', w, p)][b] = icw / np.mean(T + w * N)
    for k, v in acc.items():
        lo, hi = np.percentile(v, [2.5, 97.5])
        res['%s_w%s_p%d' % k] = [float(lo), float(hi), 'below' if hi < 1 else ('above' if lo > 1 else 'not resolved')]
    return res

if len(sys.argv) > 2 and sys.argv[2] == 'boot':
    out['boot'] = {nm: boot(rr, B=int(sys.argv[3]) if len(sys.argv) > 3 else 20000) for nm, rr in sets.items()}

# ---------- F. homogeneity (permutation ANOVA F and KW H) ----------
def anova_F(groups):
    allv = np.concatenate(groups); gmn = allv.mean(); k = len(groups); n = len(allv)
    ssb = sum(len(g) * (g.mean() - gmn) ** 2 for g in groups); ssw = sum(((g - g.mean()) ** 2).sum() for g in groups)
    return (ssb / (k - 1)) / (ssw / (n - k))

def kw_H(groups):
    allv = np.concatenate(groups); n = len(allv)
    ranks = np.empty(n); order = np.argsort(allv, kind='mergesort'); ranks[order] = np.arange(1, n + 1)
    # ties: average ranks
    vals, inv, cnt = np.unique(allv, return_inverse=True, return_counts=True)
    if (cnt > 1).any():
        sums = np.zeros(len(vals)); np.add.at(sums, inv, ranks); ranks = (sums / cnt)[inv]
    H = 0; i = 0
    for g in groups:
        rg = ranks[i:i + len(g)]; i += len(g); H += len(g) * (rg.mean() - (n + 1) / 2) ** 2
    return 12 / (n * (n + 1)) * H

if len(sys.argv) > 2 and sys.argv[2] == 'boot':
    hom = {}
    for nm, rr in sets.items():
        gs = [np.array([fresh[(p, s, r)]['steps'] / math.sqrt(fresh[(p, s, r)]['l']) for s in SEEDS for r in rr]) for p in PRIMES]
        F0, H0 = anova_F(gs), kw_H(gs)
        allv = np.concatenate(gs); sz = [len(g) for g in gs]
        rng = np.random.default_rng(777); cf = ch = 0; P = 20000
        for _ in range(P):
            perm = rng.permutation(allv); parts = np.split(perm, np.cumsum(sz)[:-1])
            cf += anova_F(parts) >= F0; ch += kw_H(parts) >= H0
        hom[nm] = dict(F=F0, H=H0, perm_p_F=(cf + 1) / (P + 1), perm_p_H=(ch + 1) / (P + 1))
    out['homogeneity'] = hom

json.dump(out, open(sys.argv[1], 'w'), indent=1, default=str)
print('written', sys.argv[1])

